package dev.jarofcucumbers.prscraft;
import java.util.*;
/** Fixed-size slots: sync(2), seq(2), count(2), original length(2), length(1), padded payload, CRC32(4). */
public final class PacketCodec{
    private PacketCodec(){}
    public static BitStream encode(BitStream input,int payload){byte[] source=input.aligned();new ProtocolSettings(payload,0,0,.05);int count=Math.max(1,(source.length+payload-1)/payload);var bytes=new java.io.ByteArrayOutputStream();for(int seq=0;seq<count;seq++){byte[] frame=new byte[payload+9];frame[0]=(byte)0xa7;frame[1]=(byte)0xd3;put(frame,2,seq);put(frame,4,count);put(frame,6,source.length);int n=Math.min(payload,source.length-seq*payload);frame[8]=(byte)n;System.arraycopy(source,seq*payload,frame,9,n);bytes.writeBytes(ChannelCoding.crcEncode(BitStream.of(frame)).bytes());}return BitStream.of(bytes.toByteArray());}
    private static void put(byte[] a,int at,int v){a[at]=(byte)(v>>>8);a[at+1]=(byte)v;}private static int u16(byte[] a,int at){return (a[at]&255)*256+(a[at+1]&255);}
    public static final class Reception{
        private final ProtocolSettings cfg;private byte[][] received;private boolean[] acknowledged;private int original=-1;private int rejected,duplicates,ackLost,attempts,transmissions;private long transmittedBits;
        public Reception(ProtocolSettings cfg){this.cfg=cfg;}
        public boolean accept(BitStream bits,long seed){byte[] bytes=bits.aligned();int size=cfg.payloadBytes()+13;if(bytes.length==0||bytes.length%size!=0)throw new IllegalArgumentException("packet_size");int count=bytes.length/size;if(received==null){if(count>256)throw new IllegalArgumentException("data_size");received=new byte[count][];acknowledged=new boolean[count];}if(count!=received.length)throw new IllegalArgumentException("packet_size");attempts++;var random=new Random(seed);
            for(int seq=0;seq<count;seq++){transmissions++;transmittedBits+=size*8L;byte[] frame;try{frame=ChannelCoding.crcDecode(BitStream.of(Arrays.copyOfRange(bytes,seq*size,(seq+1)*size))).aligned();}catch(IllegalArgumentException e){rejected++;continue;}int length=u16(frame,6),n=frame[8]&255;boolean valid=(frame[0]&255)==0xa7&&(frame[1]&255)==0xd3&&u16(frame,2)==seq&&u16(frame,4)==count&&length<=BitStream.MAX_BYTES&&count==Math.max(1,(length+cfg.payloadBytes()-1)/cfg.payloadBytes())&&n==Math.min(cfg.payloadBytes(),length-seq*cfg.payloadBytes())&&(original<0||original==length);if(!valid){rejected++;continue;}boolean padding=true;for(int i=9+n;i<frame.length;i++)if(frame[i]!=0)padding=false;if(!padding){rejected++;continue;}original=length;if(received[seq]!=null)duplicates++;else received[seq]=Arrays.copyOfRange(frame,9,9+n);if(random.nextDouble()<cfg.ackLoss())ackLost++;else acknowledged[seq]=true;}
            return complete();
        }
        public boolean complete(){if(acknowledged==null)return false;for(boolean ack:acknowledged)if(!ack)return false;return true;}
        public boolean delivered(){if(received==null)return false;for(byte[] bytes:received)if(bytes==null)return false;return true;}
        public BitStream result(){if(!delivered())throw new IllegalArgumentException("packet_arq");var out=new java.io.ByteArrayOutputStream();for(byte[] bytes:received)out.writeBytes(bytes);return BitStream.of(out.toByteArray());}
        public net.minecraft.nbt.CompoundTag statistics(double rate){var t=new net.minecraft.nbt.CompoundTag();t.putString("operation","packet_decode");t.putInt("inputBits",received==null?0:received.length*(cfg.payloadBytes()+13)*8);t.putInt("outputBits",delivered()?original*8:t.getInt("inputBits"));t.putInt("headerBytes",received==null?0:received.length*13);t.putInt("frames",received==null?0:received.length);t.putInt("attempts",attempts);t.putInt("retries",Math.max(0,attempts-1));t.putInt("transmissions",transmissions);t.putInt("rejected",rejected);t.putInt("duplicates",duplicates);t.putInt("ackLost",ackLost);t.putBoolean("delivered",delivered());t.putBoolean("acknowledged",complete());t.putLong("transmittedBits",transmittedBits);double seconds=transmittedBits/rate+Math.max(0,attempts-1)*cfg.timeout();t.putDouble("seconds",seconds);t.putDouble("goodput",delivered()&&seconds>0?original*8/seconds:0);return t;}
    }
}
